def cmd_load_seed(client: gel.Client, filepath: str) -> None:
    """Load seed data. Uses per-tenant admin identities for ticket operations."""
    with open(filepath, "r") as f:
        data = json.load(f)

    tenants_count = 0
    actors_count = 0
    tickets_count = 0

    # Upsert tenants — no access policies restrict Tenant type
    for t in data.get("tenants", []):
        existing = client.query(
            "select Tenant filter .slug = <str>$slug",
            slug=t["slug"],
        )
        if not existing:
            client.query(
                "insert Tenant { slug := <str>$slug, name := <str>$name }",
                slug=t["slug"],
                name=t["name"],
            )
        else:
            client.query(
                "update Tenant filter .slug = <str>$slug set { name := <str>$name }",
                slug=t["slug"],
                name=t["name"],
            )
        tenants_count += 1

    # Upsert actors — no access policies restrict Actor type
    for a in data.get("actors", []):
        existing = client.query(
            "select Actor filter .email = <str>$email",
            email=a["email"],
        )
        if not existing:
            client.query(
                """
                insert Actor {
                    email := <str>$email,
                    tenant := (select Tenant filter .slug = <str>$tenant),
                    role := <ActorRole>$role,
                }
                """,
                email=a["email"],
                tenant=a["tenant"],
                role=a["role"],
            )
        else:
            client.query(
                """
                update Actor
                filter .email = <str>$email
                set {
                    tenant := (select Tenant filter .slug = <str>$tenant),
                    role := <ActorRole>$role,
                }
                """,
                email=a["email"],
                tenant=a["tenant"],
                role=a["role"],
            )
        actors_count += 1

    # Build a map of tenant -> admin email for ticket operations
    tenant_admins: dict[str, str] = {}
    for a in data.get("actors", []):
        if a["role"] == "admin" and a["tenant"] not in tenant_admins:
            tenant_admins[a["tenant"]] = a["email"]

    # Upsert tickets — each must be done under the tenant's admin identity
    for tk in data.get("tickets", []):
        tenant_slug = tk["tenant"]
        admin_email = tenant_admins.get(tenant_slug)
        if admin_email is None:
            continue

        admin_client = client.with_globals(
            {"current_actor_email": admin_email}
        )
        try:
            existing = admin_client.query(
                """
                select Ticket filter .ref = <str>$ref
                """,
                ref=tk["ref"],
            )
            if not existing:
                admin_client.query(
                    """
                    insert Ticket {
                        ref := <str>$ref,
                        subject := <str>$subject,
                        status := <TicketStatus>$status,
                        tenant := (select Tenant filter .slug = <str>$tenant),
                    }
                    """,
                    ref=tk["ref"],
                    subject=tk["subject"],
                    status=tk["status"],
                    tenant=tenant_slug,
                )
            else:
                admin_client.query(
                    """
                    update Ticket
                    filter .ref = <str>$ref
                    set {
                        subject := <str>$subject,
                        status := <TicketStatus>$status,
                    }
                    """,
                    ref=tk["ref"],
                    subject=tk["subject"],
                    status=tk["status"],
                )
        finally:
            admin_client.close()
        tickets_count += 1

    print(json.dumps({
        "tenants": tenants_count,
        "actors": actors_count,
        "tickets": tickets_count,
    }))


def parse_args(argv):
    parser = argparse.ArgumentParser(prog="app.py")
    subcommands = parser.add_subparsers(dest="command")

    whoami = subcommands.add_parser("whoami")
    whoami.add_argument("--actor", required=True)

    listing = subcommands.add_parser("list-tickets")
    listing.add_argument("--actor", required=True)

    creating = subcommands.add_parser("create-ticket")
    creating.add_argument("--actor", required=True)
    creating.add_argument("--tenant", required=True)
    creating.add_argument("--ref", required=True)
    creating.add_argument("--subject", required=True)

    updating = subcommands.add_parser("update-ticket")
    updating.add_argument("--actor", required=True)
    updating.add_argument("--ref", required=True)
    updating.add_argument("--subject", default=None)
    updating.add_argument("--status", default=None)
    updating.add_argument("--tenant", default=None)

    deleting = subcommands.add_parser("delete-ticket")
    deleting.add_argument("--actor", required=True)
    deleting.add_argument("--ref", required=True)

    loading = subcommands.add_parser("load-seed")
    loading.add_argument("--file", required=True)

    return parser.parse_args(argv)


def main(argv):
    args = parse_args(argv)

    if hasattr(args, "status") and args.status is not None:
        if args.status not in VALID_STATUSES:
            die(2, "error: malformed invocation")

    if args.command == "update-ticket":
        if args.subject is None and args.status is None and args.tenant is None:
            die(2, "error: malformed invocation")

    client = gel.create_client()

    try:
        if args.command == "load-seed":
            cmd_load_seed(client, args.file)
        else:
            client_with_global = client.with_globals(
                {"current_actor_email": args.actor}
            )
            try:
                if args.command == "whoami":
                    cmd_whoami(client_with_global, args.actor)
                elif args.command == "list-tickets":
                    cmd_list_tickets(client_with_global, args.actor)
                elif args.command == "create-ticket":
                    cmd_create_ticket(
                        client_with_global,
                        args.actor,
                        args.tenant,
                        args.ref,
                        args.subject,
                    )
                elif args.command == "update-ticket":
                    cmd_update_ticket(
                        client_with_global,
                        args.actor,
                        args.ref,
                        args.subject,
                        args.status,
                        args.tenant,
                    )
                elif args.command == "delete-ticket":
                    cmd_delete_ticket(client_with_global, args.actor, args.ref)
            finally:
                client_with_global.close()
    finally:
        client.close()

    return 0


if __name__ == "__main__":
    try:
        sys.exit(main(sys.argv[1:]))
    except SystemExit:
        raise
    except gel.errors.AccessPolicyError:
        die(3, "error: denied")
    except Exception:
        die(3, "error: denied")

module default {
  scalar type ActorRole extending enum<admin, agent, readonly>;
  scalar type TicketStatus extending enum<open, pending, closed>;

  global current_actor_email: str;

  type Tenant {
    required slug: str {
      constraint exclusive;
    }
    required name: str;
  }

  type Actor {
    required email: str {
      constraint exclusive;
    }
    required tenant: Tenant;
    required role: ActorRole;
  }

  type Ticket {
    required ref: str;
    required subject: str;
    required status: TicketStatus {
      default := TicketStatus.open;
    }
    required tenant: Tenant;

    constraint exclusive on ((.ref, .tenant));

    # -- Access policies: tenant isolation enforced by the database --

    # Select: only show tickets belonging to the current actor's tenant.
    # When current_actor_email is unset or matches no Actor, no tickets visible.
    access policy tenant_select
      allow select
      using (
        .tenant = assert_exists((
          select Actor
          filter .email = global current_actor_email
        )).tenant
      );

    # Insert: actor must be admin or agent and the new ticket's tenant
    # must be the actor's own tenant.
    access policy tenant_insert
      allow insert
      using (
        .tenant = assert_exists((
          select Actor
          filter .email = global current_actor_email
             and .role in {ActorRole.admin, ActorRole.agent}
        )).tenant
      );

    # Update read: actor must be admin or agent and ticket belongs to
    # the actor's tenant.
    access policy tenant_update_read
      allow update read
      using (
        .tenant = assert_exists((
          select Actor
          filter .email = global current_actor_email
             and .role in {ActorRole.admin, ActorRole.agent}
        )).tenant
      );

    # Update write: the ticket's tenant must still match the actor's tenant
    # after the update.
    access policy tenant_update_write
      allow update write
      using (
        .tenant = assert_exists((
          select Actor
          filter .email = global current_actor_email
             and .role in {ActorRole.admin, ActorRole.agent}
        )).tenant
      );

    # Delete: actor must be admin and ticket belongs to actor's tenant.
    access policy tenant_delete
      allow delete
      using (
        .tenant = assert_exists((
          select Actor
          filter .email = global current_actor_email
             and .role = ActorRole.admin
        )).tenant
      );
  }
}

